### 1. \`internal/webui/frontend/src/hooks/ui/usePanelHistory.ts\`

New hook that manages a stack of issue IDs for in-panel back navigation.

\`\`\`typescript
import { useState, useCallback, useRef } from "react";

const MAX_STACK_DEPTH = 50;

export interface UsePanelHistoryReturn {
  /** Whether there is history to go back to. */
  canGoBack: boolean;
  /** Push the current issue ID onto the history stack (call before navigating away). */
  push: (issueId: string) => void;
  /** Pop and return the most recent issue ID from the stack. Returns null if empty. */
  pop: () => string | null;
  /** Clear the entire history stack. */
  clear: () => void;
  /** Current stack depth (for testing/debugging). */
  depth: number;
}

export function usePanelHistory(): UsePanelHistoryReturn {
  const [stack, setStack] = useState<string[]>([]);
  // Ref mirror for pop() to avoid stale closure in callbacks that 
  // don't list stack as a dependency.
  const stackRef = useRef(stack);
  stackRef.current = stack;

  const push = useCallback((issueId: string) => {
    setStack((prev) => {
      const next = [...prev, issueId];
      // Cap depth: drop oldest if over limit
      if (next.length > MAX_STACK_DEPTH) {
        next.shift();
      }
      return next;
    });
  }, []);

  const pop = useCallback((): string | null => {
    const current = stackRef.current;
    if (current.length === 0) return null;
    const last = current[current.length - 1];
    setStack((prev) => prev.slice(0, -1));
    return last;
  }, []);

  const clear = useCallback(() => {
    setStack([]);
  }, []);

  return {
    canGoBack: stack.length > 0,
    push,
    pop,
    clear,
    depth: stack.length,
  };
}
\`\`\`

