// yieldFileName is the sentinel file written by RequestYield (task .6).
// Defined locally to avoid a dependency on daemon_yield.go which may not exist yet.
// When task .6 lands, replace with the canonical YieldFileName constant.
const yieldFileName = ".agent.yield"

// isYieldExit returns true if the yield file exists in the agent worktree,
// indicating the agent exited in response to a cooperative yield request.
func isYieldExit(worktreePath string) bool {
    _, err := os.Stat(filepath.Join(worktreePath, yieldFileName))
    return err == nil
}

// readYieldReason reads the yield file and extracts the reason field.
// Returns "unknown" if the file cannot be read or parsed.
func readYieldReason(worktreePath string) string {
    data, err := os.ReadFile(filepath.Join(worktreePath, yieldFileName))
    if err != nil {
        return "unknown"
    }
    var req struct{ Reason string `json:"reason"` }
    if json.Unmarshal(data, &req) != nil || req.Reason == "" {
        return "unknown"
    }
    return req.Reason
}
```

