          body: JSON.stringify({ agents, timestamp: "2026-01-24T12:00:00Z" }),
        });
      } else if (url.includes("/api/loom/api/status")) {
        const status = options?.emptyAgents
          ? { ...mockLoomStatus, agents: [], agent_tasks: {} }
          : mockLoomStatus;
        await route.fulfill({
          status: 200,
          contentType: "application/json",
          body: JSON.stringify(status),
