**Implementation outline:**

```typescript
// Safe localStorage helpers — handle corruption gracefully
function loadFromStorage<T>(key: string, fallback: T): T {
  try {
    const stored = localStorage.getItem(key);
    if (stored === null) return fallback;
    return JSON.parse(stored) as T;
  } catch {
    return fallback;
  }
}

export function useDiff(options: UseDiffOptions): UseDiffReturn {
  const { agentName, enabled = true, commitLimit = 100 } = options;

  // --- Commits state ---
  const [commits, setCommits] = useState<DiffCommit[]>([]);
  const [commitsLoading, setCommitsLoading] = useState(false);
  const [commitsError, setCommitsError] = useState<Error | null>(null);

  // --- Selection state ---
  const [selectedFrom, setSelectedFrom] = useState<string | null>(null);
  const [selectedTo, setSelectedTo] = useState<string | null>(null);
  const [selectedFilePath, setSelectedFilePath] = useState<string | null>(null);

  // --- Files state ---
  const [files, setFiles] = useState<DiffFile[]>([]);
  const [filesLoading, setFilesLoading] = useState(false);
  const [filesError, setFilesError] = useState<Error | null>(null);

  // --- File patch state (unified diff) ---
  const [filePatch, setFilePatch] = useState<DiffFilePatch | null>(null);
  const [filePatchLoading, setFilePatchLoading] = useState(false);
  const [filePatchError, setFilePatchError] = useState<Error | null>(null);

  // --- localStorage state (with try-catch for corruption) ---
  const [reviewedPaths, setReviewedPaths] = useState<Set<string>>(() => {
    const arr = loadFromStorage<string[]>(`diff-reviewed-${agentName}`, []);
    return new Set(arr);
  });

  const [comments, setComments] = useState<InlineComment[]>(() =>
    loadFromStorage<InlineComment[]>(`diff-comments-${agentName}`, [])
  );

  // --- Refs ---
  const mountedRef = useRef(true);
  const commitsAbortRef = useRef<AbortController | null>(null);
  const filesAbortRef = useRef<AbortController | null>(null);
  const filePatchAbortRef = useRef<AbortController | null>(null);

  // --- Persist reviewedPaths to localStorage ---
  useEffect(() => {
    localStorage.setItem(
      `diff-reviewed-${agentName}`,
      JSON.stringify([...reviewedPaths])
    );
  }, [reviewedPaths, agentName]);

  // --- Persist comments to localStorage ---
  useEffect(() => {
    localStorage.setItem(
      `diff-comments-${agentName}`,
      JSON.stringify(comments)
    );
  }, [comments, agentName]);

  // --- Fetch commits ---
  const fetchCommits = useCallback(async () => {
    commitsAbortRef.current?.abort();
    const controller = new AbortController();
    commitsAbortRef.current = controller;

    setCommitsLoading(true);
    try {
      const result = await fetchDiffCommits(agentName, commitLimit);
      if (mountedRef.current && !controller.signal.aborted) {
        setCommits(result);
        setCommitsError(null);
        // Auto-select: if >= 2 commits and no selection, show latest commit's changes
        if (result.length >= 2 && !selectedFrom && !selectedTo) {
          setSelectedFrom(result[result.length - 2].hash);
          setSelectedTo(result[result.length - 1].hash);
        } else if (result.length === 1 && !selectedTo) {
          // Single commit: diff against empty tree
          setSelectedFrom("");
          setSelectedTo(result[0].hash);
        }
      }
    } catch (err) {
      if (mountedRef.current && !controller.signal.aborted) {
        setCommitsError(err instanceof Error ? err : new Error(String(err)));
      }
    } finally {
      if (mountedRef.current && !controller.signal.aborted) {
        setCommitsLoading(false);
      }
    }
  }, [agentName, commitLimit]);
  // Note: selectedFrom/selectedTo intentionally excluded to avoid refetch loop

  // --- Fetch files when range changes ---
  const fetchFilesForRange = useCallback(async () => {
    // selectedFrom can be "" (empty tree) or a hash; selectedTo must be set
    if (selectedFrom === null || !selectedTo) {
      setFiles([]);
      return;
    }

    filesAbortRef.current?.abort();
    const controller = new AbortController();
    filesAbortRef.current = controller;

    setFilesLoading(true);
    setSelectedFilePath(null); // Reset file selection when range changes
    setFilePatch(null);
    try {
      const result = await fetchDiffFiles(agentName, selectedFrom, selectedTo);
      if (mountedRef.current && !controller.signal.aborted) {
        setFiles(result);
        setFilesError(null);
      }
    } catch (err) {
      if (mountedRef.current && !controller.signal.aborted) {
        setFilesError(err instanceof Error ? err : new Error(String(err)));
      }
    } finally {
      if (mountedRef.current && !controller.signal.aborted) {
        setFilesLoading(false);
      }
    }
  }, [agentName, selectedFrom, selectedTo]);

  // --- Fetch file patch when file selection changes ---
  const fetchFilePatch = useCallback(async () => {
    if (!selectedFilePath || selectedFrom === null || !selectedTo) {
      setFilePatch(null);
      return;
    }

    filePatchAbortRef.current?.abort();
    const controller = new AbortController();
    filePatchAbortRef.current = controller;

    setFilePatchLoading(true);
    try {
      const result = await fetchDiffFile(
        agentName, selectedFilePath, selectedFrom, selectedTo
      );
      if (mountedRef.current && !controller.signal.aborted) {
        setFilePatch(result);
        setFilePatchError(null);
      }
    } catch (err) {
      if (mountedRef.current && !controller.signal.aborted) {
        setFilePatchError(err instanceof Error ? err : new Error(String(err)));
      }
    } finally {
      if (mountedRef.current && !controller.signal.aborted) {
        setFilePatchLoading(false);
      }
    }
  }, [agentName, selectedFilePath, selectedFrom, selectedTo]);

  // --- Effects to trigger fetches ---

  // Fetch commits on mount / when enabled changes
  useEffect(() => {
    mountedRef.current = true;
    if (!enabled) return;
    void fetchCommits();
    return () => {
      mountedRef.current = false;
      commitsAbortRef.current?.abort();
    };
  }, [enabled, fetchCommits]);

  // Fetch files when commit range changes
  useEffect(() => {
    if (!enabled || selectedFrom === null || !selectedTo) return;
    void fetchFilesForRange();
    return () => {
      filesAbortRef.current?.abort();
    };
  }, [enabled, fetchFilesForRange, selectedFrom, selectedTo]);

  // Fetch file patch when file selection changes
  useEffect(() => {
    if (!enabled || !selectedFilePath) return;
    void fetchFilePatch();
    return () => {
      filePatchAbortRef.current?.abort();
    };
  }, [enabled, fetchFilePatch, selectedFilePath]);

  // --- Turn-by-turn navigation ---
  const commitIndex = useMemo(() => {
    // selectedFrom can be "" for empty tree — findIndex returns -1 which is correct
    const fromIdx = commits.findIndex((c) => c.hash === selectedFrom);
    const toIdx = commits.findIndex((c) => c.hash === selectedTo);
    return { fromIdx, toIdx };
  }, [commits, selectedFrom, selectedTo]);

  // canGoPrev: false when selectedFrom is "" (empty tree, already at start)
  const canGoPrev = commitIndex.fromIdx > 0;
  const canGoNext = commitIndex.toIdx < commits.length - 1;

  const goPrev = useCallback(() => {
    if (!canGoPrev) return;
    const span = commitIndex.toIdx - commitIndex.fromIdx;
    const newFromIdx = commitIndex.fromIdx - 1;
    const newToIdx = newFromIdx + span;
    setSelectedFrom(commits[newFromIdx].hash);
    setSelectedTo(commits[newToIdx].hash);
  }, [canGoPrev, commitIndex, commits]);

  const goNext = useCallback(() => {
    if (!canGoNext) return;
    const span = commitIndex.toIdx - commitIndex.fromIdx;
    const newToIdx = commitIndex.toIdx + 1;
    const newFromIdx = newToIdx - span;
    setSelectedFrom(commits[newFromIdx].hash);
    setSelectedTo(commits[newToIdx].hash);
  }, [canGoNext, commitIndex, commits]);

  const selectSingleCommit = useCallback(
    (hash: string) => {
      const idx = commits.findIndex((c) => c.hash === hash);
      if (idx < 0) return;
      if (idx === 0) {
        // First commit: diff against empty tree using empty string for from
        setSelectedFrom("");
        setSelectedTo(commits[0].hash);
      } else {
        setSelectedFrom(commits[idx - 1].hash);
        setSelectedTo(commits[idx].hash);
      }
    },
    [commits]
  );

  // --- Reviewed paths ---
  const toggleReviewed = useCallback((path: string) => {
    setReviewedPaths((prev) => {
      const next = new Set(prev);
      if (next.has(path)) {
        next.delete(path);
      } else {
        next.add(path);
      }
      return next;
    });
  }, []);

  const clearReviewed = useCallback(() => {
    setReviewedPaths(new Set());
  }, []);

  const reviewProgress = useMemo(
    () => ({
      reviewed: files.filter((f) => reviewedPaths.has(f.path)).length,
      total: files.length,
    }),
    [files, reviewedPaths]
  );

  // --- Inline comments ---
  const addCommentFn = useCallback(
    (filePath: string, lineNumber: number, content: string) => {
      const comment: InlineComment = {
        id: crypto.randomUUID(),
        filePath,
        lineNumber,
        content,
        createdAt: new Date().toISOString(),
      };
      setComments((prev) => [...prev, comment]);
    },
    []
  );

  const removeComment = useCallback((commentId: string) => {
    setComments((prev) => prev.filter((c) => c.id !== commentId));
  }, []);

  const getCommentsForFile = useCallback(
    (filePath: string) => comments.filter((c) => c.filePath === filePath),
    [comments]
  );

  // --- Refetch all ---
  const refetch = useCallback(async () => {
    await fetchCommits();
  }, [fetchCommits]);

  return {
    commits, commitsLoading, commitsError,
    selectedFrom, selectedTo, setSelectedFrom, setSelectedTo, selectSingleCommit,
    goNext, goPrev, canGoNext, canGoPrev,
    files, filesLoading, filesError,
    selectedFilePath, setSelectedFilePath,
    filePatch, filePatchLoading, filePatchError,
    reviewedPaths, toggleReviewed, clearReviewed, reviewProgress,
    comments, addComment: addCommentFn, removeComment, getCommentsForFile,
    refetch,
  };
}
```

