Contains all types, handlers, and the editor cache for the two endpoints.

**Types:**
```go
// EditorInfo is the JSON representation of an editor for the API response.
type EditorInfo struct {
    ID          string `json:"id"`
    DisplayName string `json:"display_name"`
    IconName    string `json:"icon_name"`
    Detected    bool   `json:"detected"`
}

// EditorsListResponse is the response for GET /api/editors.
type EditorsListResponse struct {
    Editors []EditorInfo `json:"editors"`
}

// EditorOpenRequest is the JSON body for POST /api/editors/open.
type EditorOpenRequest struct {
    EditorID string `json:"editor_id"`
    Path     string `json:"path"`
}

// editorCache holds cached detection results with TTL.
type editorCache struct {
    mu       sync.Mutex
    editors  []editor.DetectedEditor
    cachedAt time.Time
    ttl      time.Duration
}
```

**Cache implementation:**
```go
const editorCacheTTL = 30 * time.Second

func newEditorCache(ttl time.Duration) *editorCache {
    return &editorCache{ttl: ttl}
}

func newDefaultEditorCache() *editorCache {
    return newEditorCache(editorCacheTTL)
}

func (c *editorCache) get() []editor.DetectedEditor {
    c.mu.Lock()
    defer c.mu.Unlock()
    if time.Since(c.cachedAt) > c.ttl {
        c.editors = editor.DetectedEditors()
        c.cachedAt = time.Now()
    }
    return c.editors
}
```

**Handler: GET /api/editors**
```go
func handleListEditors(cache *editorCache) http.HandlerFunc {
    return func(w http.ResponseWriter, r *http.Request) {
        detected := cache.get()

        // Build response: include all editors from registry, marking which are detected
        infos := make([]EditorInfo, 0, len(editor.Registry))
        detectedSet := make(map[string]bool, len(detected))
        for _, de := range detected {
            detectedSet[de.ID] = true
        }
        for _, e := range editor.Registry {
            infos = append(infos, EditorInfo{
                ID:          e.ID,
                DisplayName: e.DisplayName,
                IconName:    e.IconName,
                Detected:    detectedSet[e.ID],
            })
        }

        respondJSON(w, http.StatusOK, EditorsListResponse{Editors: infos})
    }
}
```

**Handler: POST /api/editors/open**
```go
// validEditorID matches editor IDs (lowercase alphanumeric + hyphens).
var validEditorID = regexp.MustCompile(`^[a-z0-9-]+$`)

func handleOpenEditor(cache *editorCache) http.HandlerFunc {
    return func(w http.ResponseWriter, r *http.Request) {
        // 1. Limit request body size
        r.Body = http.MaxBytesReader(w, r.Body, 1<<20) // 1MB

        // 2. Decode request
        var req EditorOpenRequest
        if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
            respondError(w, http.StatusBadRequest, "invalid JSON body")
            return
        }

        // 3. Validate editor_id
        if req.EditorID == "" {
            respondError(w, http.StatusBadRequest, "editor_id is required")
            return
        }
        if !validEditorID.MatchString(req.EditorID) {
            respondError(w, http.StatusBadRequest, "invalid editor_id format")
            return
        }

        // 4. Validate path — reject ".." components for security
        if req.Path == "" {
            respondError(w, http.StatusBadRequest, "path is required")
            return
        }
        cleanPath := filepath.Clean(req.Path)
        for _, part := range strings.Split(filepath.ToSlash(cleanPath), "/") {
            if part == ".." {
                respondError(w, http.StatusUnprocessableEntity, "path must not contain '..' components")
                return
            }
        }

        // 5. Verify path exists on disk
        if _, err := os.Stat(cleanPath); err != nil {
            if os.IsNotExist(err) {
                respondError(w, http.StatusNotFound, "path does not exist")
                return
            }
            respondError(w, http.StatusInternalServerError, "failed to verify path")
            return
        }

        // 6. Look up editor in detected editors
        detected := cache.get()
        var found *editor.DetectedEditor
        for i := range detected {
            if detected[i].ID == req.EditorID {
                found = &detected[i]
                break
            }
        }
        if found == nil {
            // Distinguish "unknown editor" (404) from "not detected" (422)
            exists := false
            for _, e := range editor.Registry {
                if e.ID == req.EditorID {
                    exists = true
                    break
                }
            }
            if !exists {
                respondError(w, http.StatusNotFound, "unknown editor: "+req.EditorID)
            } else {
                respondError(w, http.StatusUnprocessableEntity, "editor not detected on this system: "+req.EditorID)
            }
            return
        }

        // 7. Launch the editor (fire-and-forget)
        if err := editor.LaunchEditor(*found, []string{cleanPath}); err != nil {
            respondError(w, http.StatusInternalServerError, "failed to launch editor: "+err.Error())
            return
        }

        respondJSON(w, http.StatusOK, map[string]bool{"success": true})
    }
}
```

**HTTP status code summary:**
- 200: Success (GET list, POST launch)
- 400: Bad request (missing/invalid fields, malformed JSON)
- 404: Not found (unknown editor_id, path doesn't exist)
- 422: Unprocessable (path traversal, editor exists but not detected)
- 500: Internal error (stat failure, launch failure)

