## Mock Setup Pattern

```typescript
const mockBackendConfig = {
  backend: \"claude\",
  source: \"project\",
  available: [\"claude\", \"codex\", \"opencode\", \"gemini\", \"cursor\", \"shell\"],
  agents: [],
};

async function setupMocks(page: Page, configOverrides?: Partial<typeof mockBackendConfig>) {
  const config = { ...mockBackendConfig, ...configOverrides };

  // Backend config endpoint
  await page.route(\"**/api/config/backend\", async (route) => {
    if (route.request().method() === \"GET\") {
      await route.fulfill({
        status: 200,
        contentType: \"application/json\",
        body: JSON.stringify({ success: true, data: config }),
      });
    } else if (route.request().method() === \"PATCH\") {
      const body = route.request().postDataJSON();
      await route.fulfill({
        status: 200,
        contentType: \"application/json\",
        body: JSON.stringify({ success: true, data: { ...config, ...body } }),
      });
    }
  });

  // Standard mocks (SSE, ready, stats)
  await page.route(\"**/api/events\", async (route) => { await route.abort(); });
  await page.route(\"**/api/ready\", async (route) => {
    await route.fulfill({ status: 200, contentType: \"application/json\", body: JSON.stringify({ success: true, data: [] }) });
  });
  await page.route(\"**/api/stats\", async (route) => {
    await route.fulfill({ status: 200, contentType: \"application/json\", body: JSON.stringify({ success: true, data: { open: 0, closed: 0, total: 0 } }) });
  });
}
```

