### 2. \`internal/webui/server/handler/errors.go\`

Service error to HTTP response mapping:

\`\`\`go
package handler

import (
    "errors"
    "log/slog"
    "net/http"

    "github.com/tysonthomas9/loomcli/internal/webui/service"
)

// kindToStatus maps each service.ErrorKind to its HTTP status code.
// This must stay in sync with service/errors.go (task .9).
var kindToStatus = map[service.ErrorKind]int{
    service.KindNotFound:        http.StatusNotFound,            // 404
    service.KindValidation:      http.StatusBadRequest,          // 400
    service.KindUnavailable:     http.StatusServiceUnavailable,  // 503
    service.KindTimeout:         http.StatusGatewayTimeout,      // 504
    service.KindConflict:        http.StatusConflict,            // 409
    service.KindInternal:        http.StatusInternalServerError, // 500
    service.KindForbidden:       http.StatusForbidden,           // 403
    service.KindUnauthorized:    http.StatusUnauthorized,        // 401
    service.KindLocked:          423,                            // http.StatusLocked (Go 1.24+)
    service.KindPayloadTooLarge: http.StatusRequestEntityTooLarge, // 413
    service.KindRateLimited:     http.StatusTooManyRequests,     // 429
    service.KindBadGateway:      http.StatusBadGateway,          // 502
    service.KindNotImplemented:  http.StatusNotImplemented,      // 501
}

// HandleServiceError extracts a *service.ServiceError from err, maps its
// Kind to an HTTP status code, logs the full error, and writes a JSON error
// response. If err is not a *service.ServiceError, it writes 500 with a
// generic message.
//
// The response body is always {"error": "<message>"}. The message comes from
// ServiceError.Message (not Error()) to avoid leaking cause chains to clients.
func HandleServiceError(w http.ResponseWriter, err error) {
    var svcErr *service.ServiceError
    if errors.As(err, &svcErr) {
        status, ok := kindToStatus[svcErr.Kind]
        if !ok {
            status = http.StatusInternalServerError
        }
        slog.Error("service error",
            "kind", string(svcErr.Kind),
            "status", status,
            "msg", svcErr.Message,
            "err", err,
        )
        WriteJSON(w, status, map[string]string{"error": svcErr.Message})
        return
    }
    slog.Error("unexpected error", "err", err)
    WriteJSON(w, http.StatusInternalServerError, map[string]string{"error": "internal server error"})
}
