#### Add \`checkStaleSignalFiles()\`:
\`\`\`go
func checkStaleSignalFiles() CheckResult {
    signalDir := getSignalDir()

    entries, err := os.ReadDir(signalDir)
    if err != nil {
        if os.IsNotExist(err) {
            return CheckResult{} // skip — no signal directory, no stale signals possible
        }
        return CheckResult{
            Name:    \"stale_signal_files\",
            Status:  StatusWarn,
            Summary: \"could not read signal directory\",
            Detail:  err.Error(),
        }
    }

    if len(entries) == 0 {
        return CheckResult{} // skip — empty directory, nothing to report
    }

    now := time.Now()
    var stale []struct {
        name string
        age  time.Duration
        path string
    }

    for _, entry := range entries {
        if entry.IsDir() {
            continue // skip subdirectories
        }
        info, err := entry.Info()
        if err != nil {
            continue
        }
        age := now.Sub(info.ModTime())
        if age > staleSignalThreshold {
            stale = append(stale, struct {
                name string
                age  time.Duration
                path string
            }{
                name: entry.Name(),
                age:  age.Truncate(time.Second),
                path: filepath.Join(signalDir, entry.Name()),
            })
        }
    }

    if len(stale) == 0 {
        return CheckResult{
            Name:    \"stale_signal_files\",
            Status:  StatusPass,
            Summary: \"no stale signal files\",
        }
    }

    // Build detail lines
    var details []string
    for _, s := range stale {
        details = append(details, fmt.Sprintf(\"%s (age=%s)\", s.name, s.age))
    }

    if doctorFix {
        fixed := 0
        var failures []string
        for _, s := range stale {
            if err := os.Remove(s.path); err != nil {
                if !os.IsNotExist(err) {
                    failures = append(failures, fmt.Sprintf(\"%s: %v\", s.name, err))
                } else {
                    fixed++ // already gone, count as success
                }
            } else {
                fixed++
            }
        }
        if len(failures) > 0 {
            return CheckResult{
                Name:    \"stale_signal_files\",
                Status:  StatusWarn,
                Summary: fmt.Sprintf(\"fixed %d stale signal file(s), %d failed\", fixed, len(failures)),
                Detail:  strings.Join(append(details, failures...), \"\\n\"),
            }
        }
        return CheckResult{
            Name:    \"stale_signal_files\",
            Status:  StatusPass,
            Summary: fmt.Sprintf(\"fixed %d stale signal file(s)\", fixed),
            Detail:  strings.Join(details, \"\\n\"),
        }
    }

    return CheckResult{
        Name:    \"stale_signal_files\",
        Status:  StatusWarn,
        Summary: fmt.Sprintf(\"%d stale signal file(s) found\", len(stale)),
        Detail:  strings.Join(details, \"\\n\") + \"\\nRun: loom doctor --fix\",
    }
}
