\`\`\`go
func checkStaleSessionRecords() CheckResult {
    beadsDir := GetBeadsDir()
    sessStore, err := sessions.NewStore(beadsDir)
    if err != nil {
        return CheckResult{} // skip — sessions store not available
    }

    // Phase 1: Check index for stale running records.
    // Use readDedupedIndex directly to avoid triggering auto-healing.
    // We need access to the raw query, so we use Query with a running filter
    // but note that Query auto-heals. Instead, we use the public interface:
    // query all records and filter for stale ones ourselves.
    records, err := sessStore.Query(sessions.Filter{Status: sessions.StatusRunning})
    if err != nil {
        return CheckResult{
            Name:    \"stale_sessions\",
            Status:  StatusWarn,
            Summary: \"could not query session index\",
            Detail:  err.Error(),
        }
    }

    // Note: Query() already auto-heals stale sessions, so records here are
    // genuinely running sessions (not yet past the threshold). We still want
    // to detect sessions that WILL become stale (older than 1 hour but not
    // yet past the 4-hour StaleSessionThreshold) as a warning.
    // However, the primary value is detecting orphaned directories.

    // Phase 2: Scan for orphaned session directories.
    sessDir := sessStore.Dir()
    dirEntries, dirErr := os.ReadDir(sessDir)
    if dirErr != nil && !os.IsNotExist(dirErr) {
        return CheckResult{
            Name:    \"stale_sessions\",
            Status:  StatusWarn,
            Summary: \"could not scan sessions directory\",
            Detail:  dirErr.Error(),
        }
    }

    // Build set of session IDs from the full index (all statuses).
    allRecords, _ := sessStore.Query(sessions.Filter{})
    indexedIDs := make(map[string]bool, len(allRecords))
    for _, rec := range allRecords {
        indexedIDs[rec.SessionID] = true
    }

    var orphanedDirs []string    // directories on disk with no index entry
    var halfWritten []string     // directories missing metadata.json
    var staleTmpFiles []string   // leftover metadata.json.tmp files

    for _, entry := range dirEntries {
        if !entry.IsDir() {
            continue // skip index.jsonl and other non-directory files
        }
        name := entry.Name()
        dirPath := filepath.Join(sessDir, name)

        // Check for missing metadata.json (half-written session).
        metaPath := filepath.Join(dirPath, \"metadata.json\")
        if _, statErr := os.Stat(metaPath); os.IsNotExist(statErr) {
            halfWritten = append(halfWritten, name)
            continue
        }

        // Check for leftover .tmp file (failed atomic write).
        tmpPath := filepath.Join(dirPath, \"metadata.json.tmp\")
        if _, statErr := os.Stat(tmpPath); statErr == nil {
            staleTmpFiles = append(staleTmpFiles, name)
        }

        // Check if directory is in the index.
        if !indexedIDs[name] {
            orphanedDirs = append(orphanedDirs, name)
        }
    }

    totalIssues := len(records) + len(orphanedDirs) + len(halfWritten) + len(staleTmpFiles)
    if totalIssues == 0 {
        return CheckResult{
            Name:    \"stale_sessions\",
            Status:  StatusPass,
            Summary: \"no stale or orphaned sessions\",
        }
    }

    // Build detail
    var details []string
    for _, rec := range records {
        age := time.Since(rec.StartedAt).Truncate(time.Second)
        details = append(details, fmt.Sprintf(\"running: %s (agent=%s age=%s)\", rec.SessionID, rec.AgentName, age))
    }
    for _, name := range halfWritten {
        details = append(details, fmt.Sprintf(\"half-written (no metadata.json): %s\", name))
    }
    for _, name := range orphanedDirs {
        details = append(details, fmt.Sprintf(\"orphaned (not in index): %s\", name))
    }
    for _, name := range staleTmpFiles {
        details = append(details, fmt.Sprintf(\"leftover tmp file: %s/metadata.json.tmp\", name))
    }

    if doctorFix {
        fixed := 0
        var failures []string

        // Fix 1: Heal stale running sessions via SweepOrphans.
        if len(records) > 0 {
            healed, sweepErr := sessStore.SweepOrphans()
            if sweepErr != nil {
                failures = append(failures, fmt.Sprintf(\"sweep orphans: %v\", sweepErr))
            } else {
                fixed += healed
            }
        }

        // Fix 2: Remove half-written session directories.
        for _, name := range halfWritten {
            dirPath := filepath.Join(sessDir, name)
            if rmErr := os.RemoveAll(dirPath); rmErr != nil {
                failures = append(failures, fmt.Sprintf(\"remove %s: %v\", name, rmErr))
            } else {
                fixed++
            }
        }

        // Fix 3: Remove leftover .tmp files.
        for _, name := range staleTmpFiles {
            tmpPath := filepath.Join(sessDir, name, \"metadata.json.tmp\")
            if rmErr := os.Remove(tmpPath); rmErr != nil && !os.IsNotExist(rmErr) {
                failures = append(failures, fmt.Sprintf(\"remove %s/metadata.json.tmp: %v\", name, rmErr))
            } else {
                fixed++
            }
        }

        // Fix 4: For orphaned dirs (have metadata.json but not in index),
        // re-index them by loading metadata and appending to index.
        // This is non-destructive — we're adding missing index entries, not deleting data.
        for _, name := range orphanedDirs {
            meta, loadErr := sessStore.LoadMetadata(name)
            if loadErr != nil {
                failures = append(failures, fmt.Sprintf(\"re-index %s: %v\", name, loadErr))
                continue
            }
            // Ensure schema is current before re-indexing.
            meta.NormalizeAfterLoad()
            if appendErr := sessStore.ReIndex(meta.SessionRecord); appendErr != nil {
                failures = append(failures, fmt.Sprintf(\"re-index %s: %v\", name, appendErr))
            } else {
                fixed++
            }
        }

        if len(failures) > 0 {
            return CheckResult{
                Name:    \"stale_sessions\",
                Status:  StatusWarn,
                Summary: fmt.Sprintf(\"fixed %d session issue(s), %d failed\", fixed, len(failures)),
                Detail:  strings.Join(append(details, failures...), \"\\n\"),
            }
        }
        return CheckResult{
            Name:    \"stale_sessions\",
            Status:  StatusPass,
            Summary: fmt.Sprintf(\"fixed %d session issue(s)\", fixed),
            Detail:  strings.Join(details, \"\\n\"),
        }
    }

    return CheckResult{
        Name:    \"stale_sessions\",
        Status:  StatusWarn,
        Summary: fmt.Sprintf(\"%d session issue(s) found\", totalIssues),
        Detail:  strings.Join(details, \"\\n\") + \"\\nRun: loom doctor --fix\",
    }
}
\`\`\`

