```typescript
import type { WorkspaceAgentStatusResponse } from "@/types";
import { get, wsUrl } from "./client";

/**
 * Fetch daemon agent supervision status for a workspace.
 * Calls GET /api/workspaces/{ws}/agents/status.
 * Throws on network errors or non-OK responses.
 */
export async function fetchWorkspaceAgentStatus(
  workspaceId: string,
): Promise<WorkspaceAgentStatusResponse> {
  const data = await get<WorkspaceAgentStatusResponse>(
    wsUrl(workspaceId, "/agents/status"),
    { timeout: 10000 },
  );
  return {
    agents: data.agents ?? [],
    ipc_socket_active: data.ipc_socket_active ?? false,
  };
}
```

The defensive `?? []` and `?? false` follow the pattern in `agents.ts:fetchAgents()` where `data.agents ?? []` guards against a null response.

