// Core comment state — Map for O(1) lookups, seeded from initialComments
const [commentsMap, setCommentsMap] = useState<Map<number, Comment>>(() =>
  new Map((initialComments ?? []).map(c => [c.id, c]))
);

// Reactions state — optimistic local tracking
const [reactionsMap, setReactionsMap] = useState<Map<number, CommentReaction[]>>(new Map());

// Reply state — which comment is being replied to
const [replyToCommentId, setReplyToCommentId] = useState<number | null>(null);

// ReactionPicker state — which comment's picker is open
const [activePickerCommentId, setActivePickerCommentId] = useState<number | null>(null);

// Refetching state
const [isRefetching, setIsRefetching] = useState(false);
\`\`\`

**Sync effect — re-seed Map when initialComments changes (issue switch):**
\`\`\`typescript
useEffect(() => {
  setCommentsMap(new Map((initialComments ?? []).map(c => [c.id, c])));
  setReactionsMap(new Map());
  setReplyToCommentId(null);
  setActivePickerCommentId(null);
}, [initialComments]);
\`\`\`

**Refetch effect — triggered by commentRefreshKey changes:**
\`\`\`typescript
const prevRefreshKeyRef = useRef(commentRefreshKey);
useEffect(() => {
  if (commentRefreshKey === undefined || commentRefreshKey === prevRefreshKeyRef.current) return;
  prevRefreshKeyRef.current = commentRefreshKey;
  refetchComments();
}, [commentRefreshKey]);
\`\`\`

**refetchComments function:**
\`\`\`typescript
const refetchComments = useCallback(async () => {
  setIsRefetching(true);
  try {
    const issueDetails = await getIssue(workspaceId, issueId);
    if (issueDetails.comments) {
      setCommentsMap(new Map(issueDetails.comments.map(c => [c.id, c])));
    }
  } catch {
    // Silently fail — stale comments are acceptable until next refetch
  } finally {
    setIsRefetching(false);
  }
}, [workspaceId, issueId]);
\`\`\`

**Threading computation (useMemo):**
\`\`\`typescript
interface ThreadedComment {
  comment: Comment;
  replies: Comment[];
}

const threadedComments = useMemo(() => {
  const topLevel: ThreadedComment[] = [];
  const repliesByParent = new Map<number, Comment[]>();

  for (const comment of commentsMap.values()) {
    if (!comment.parent_id) {
      topLevel.push({ comment, replies: [] });
    } else {
      // Two-level flattening: if parent is itself a reply, promote to root
      let rootParentId = comment.parent_id;
      const parent = commentsMap.get(rootParentId);
      if (parent && parent.parent_id) {
        rootParentId = parent.parent_id;
      }
      const existing = repliesByParent.get(rootParentId) ?? [];
      existing.push(comment);
      repliesByParent.set(rootParentId, existing);
    }
  }

  // Attach replies and sort
  const chronSort = (a: Comment, b: Comment) =>
    new Date(a.created_at).getTime() - new Date(b.created_at).getTime();

  for (const thread of topLevel) {
    thread.replies = (repliesByParent.get(thread.comment.id) ?? []).sort(chronSort);
  }

  topLevel.sort((a, b) => chronSort(a.comment, b.comment));
  return topLevel;
}, [commentsMap]);
\`\`\`

**Comment callbacks:**

handleCommentAdded — optimistic insert into Map:
\`\`\`typescript
const handleCommentAdded = useCallback((newComment: Comment) => {
  setCommentsMap(prev => {
    const next = new Map(prev);
    next.set(newComment.id, newComment);
    return next;
  });
  // Clear reply state after adding a reply
  setReplyToCommentId(null);
}, []);
\`\`\`

handleCommentUpdated — optimistic update (from CommentItem edit):
\`\`\`typescript
const handleCommentUpdated = useCallback((updated: Comment) => {
  setCommentsMap(prev => {
    const next = new Map(prev);
    next.set(updated.id, updated);
    return next;
  });
}, []);
\`\`\`

handleCommentDeleted — optimistic soft-delete:
\`\`\`typescript
const handleCommentDeleted = useCallback((commentId: number) => {
  setCommentsMap(prev => {
    const next = new Map(prev);
    const comment = next.get(commentId);
    if (comment) {
      next.set(commentId, { ...comment, deleted_at: new Date().toISOString() });
    }
    return next;
  });
}, []);
\`\`\`

handleReply — set reply state:
\`\`\`typescript
const handleReply = useCallback((commentId: number) => {
  setReplyToCommentId(commentId);
}, []);
\`\`\`

handleDismissReply:
\`\`\`typescript
const handleDismissReply = useCallback(() => {
  setReplyToCommentId(null);
}, []);
\`\`\`

handleAddReactionClick — open ReactionPicker:
\`\`\`typescript
const handleAddReactionClick = useCallback((commentId: number) => {
  setActivePickerCommentId(prev => prev === commentId ? null : commentId);
}, []);
\`\`\`

handleReactionSelect — API call + optimistic update:
\`\`\`typescript
const handleReactionSelect = useCallback(async (emoji: string) => {
  if (activePickerCommentId === null) return;
  const commentId = activePickerCommentId;
  setActivePickerCommentId(null); // close picker
  try {
    const reaction = await addReaction(workspaceId, issueId, commentId, emoji);
    setReactionsMap(prev => {
      const next = new Map(prev);
      const existing = next.get(commentId) ?? [];
      next.set(commentId, [...existing, reaction]);
      return next;
    });
  } catch {
    // Silently fail — reaction not critical
  }
}, [activePickerCommentId, workspaceId, issueId]);
\`\`\`

handleReactionPickerClose:
\`\`\`typescript
const handleReactionPickerClose = useCallback(() => {
  setActivePickerCommentId(null);
}, []);
\`\`\`

handleReactionsChanged — on CommentItem's internal reaction toggle, trigger refetch:
\`\`\`typescript
const handleReactionsChanged = useCallback((commentId: number) => {
  // CommentItem toggled a reaction via its internal API call.
  // Trigger a full refetch to sync state. This is the same approach
  // as SSE-triggered refetch since we can't do targeted updates.
  refetchComments();
