// ============= COMMENT MUTATION OPERATIONS =============

/**
 * Request body for editing a comment.
 */
export interface EditCommentRequest {
  text: string;
}

/**
 * Edit a comment's text.
 */
export async function editComment(
  workspaceId: string,
  issueId: string,
  commentId: number,
  text: string,
): Promise<void> {
  const response = await put<ApiResult<null>>(
    wsUrl(
      workspaceId,
      `/issues/${encodeURIComponent(issueId)}/comments/${commentId}`,
    ),
    { text },
  );
  unwrap(response);
}

/**
 * Soft-delete a comment.
 */
export async function deleteComment(
  workspaceId: string,
  issueId: string,
  commentId: number,
): Promise<void> {
  const response = await del<ApiResult<null>>(
    wsUrl(
      workspaceId,
      `/issues/${encodeURIComponent(issueId)}/comments/${commentId}`,
    ),
  );
  unwrap(response);
}

// ============= REACTION OPERATIONS =============

/**
 * Request body for reaction operations.
 */
export interface ReactionRequest {
  emoji: string;
}

/**
 * Add a reaction to a comment.
 */
export async function addReaction(
  workspaceId: string,
  issueId: string,
  commentId: number,
  emoji: string,
): Promise<CommentReaction> {
  const response = await post<ApiResult<CommentReaction>>(
    wsUrl(
      workspaceId,
      `/issues/${encodeURIComponent(issueId)}/comments/${commentId}/reactions`,
    ),
    { emoji },
  );
  return unwrap(response);
}

/**
 * Remove a reaction from a comment.
 * Uses DELETE with body because emoji characters are problematic in URLs.
 */
export async function removeReaction(
  workspaceId: string,
  issueId: string,
  commentId: number,
  emoji: string,
): Promise<void> {
  const response = await delWithBody<ApiResult<null>>(
    wsUrl(
      workspaceId,
      `/issues/${encodeURIComponent(issueId)}/comments/${commentId}/reactions`,
    ),
    { emoji },
  );
  unwrap(response);
}

