export interface MentionDropdownProps {
  /** Whether the dropdown is visible */
  isOpen: boolean;
  /** Filtered mention suggestions to display */
  suggestions: MentionSuggestion[];
  /** Index of the currently focused suggestion */
  focusedIndex: number;
  /** Called when a suggestion is clicked */
  onSelect: (name: string) => void;
  /** Called when the dropdown should close (click-outside) */
  onClose: () => void;
  /** Inline style for positioning (top, left) computed by parent from cursor pos */
  style?: React.CSSProperties;
  /** Additional CSS class name */
  className?: string;
