function detectMentionTrigger(value: string, cursorPos: number): { triggerPos: number; query: string } | null {
  // Scan backwards from cursor for @
  let i = cursorPos - 1;
  while (i >= 0) {
    const ch = value[i];
    if (ch === "@") {
      // @ must be at start or preceded by whitespace
      if (i === 0 || /\s/.test(value[i - 1])) {
        return { triggerPos: i, query: value.substring(i + 1, cursorPos) };
      }
      return null; // @ preceded by non-whitespace (e.g., email)
    }
    if (/\s/.test(ch)) return null; // hit whitespace before finding @
    i--;
  }
  return null;
}
```

**Modified handleTextChange** (lines 89-98):
- After setting text and clearing error, run detectMentionTrigger
- If trigger found: open mention dropdown, set query, compute dropdown position
- If trigger not found: close mention dropdown
- Fetch suggestions on first open (check mentionFetchedRef)

```typescript
const handleTextChange = useCallback(
  (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    const newValue = e.target.value;
    const cursorPos = e.target.selectionStart;
    setText(newValue);
    if (error) setError(null);

    const trigger = detectMentionTrigger(newValue, cursorPos);
    if (trigger) {
      setMentionOpen(true);
      setMentionQuery(trigger.query);
      setMentionTriggerPos(trigger.triggerPos);

      // Compute dropdown position
      if (textareaRef.current) {
        const coords = getCaretCoordinates(textareaRef.current, cursorPos);
        setMentionDropdownStyle({ top: coords.top, left: coords.left });
      }

      // Fetch suggestions once per dropdown session
      if (!mentionFetchedRef.current) {
        mentionFetchedRef.current = true;
        fetchMentionSuggestions(workspaceId, issueId)
          .then(setMentionSuggestions)
          .catch(() => setMentionSuggestions([]));
      }
    } else {
      if (mentionOpen) {
        setMentionOpen(false);
        setMentionQuery("");
        setMentionTriggerPos(-1);
        mentionFetchedRef.current = false;
      }
    }
  },
  [error, workspaceId, issueId, mentionOpen],
);
```

**Mention selection handler:**
```typescript
const handleMentionSelect = useCallback(
  (name: string) => {
    if (mentionTriggerPos < 0 || !textareaRef.current) return;
    const before = text.substring(0, mentionTriggerPos);
    const after = text.substring(textareaRef.current.selectionStart);
    const inserted = `@${name} `;
    const newText = before + inserted + after;
    setText(newText);
    setMentionOpen(false);
    setMentionQuery("");
    setMentionTriggerPos(-1);
    mentionFetchedRef.current = false;

    // Reposition cursor after inserted text
    const newCursorPos = mentionTriggerPos + inserted.length;
    requestAnimationFrame(() => {
      if (textareaRef.current) {
        textareaRef.current.selectionStart = newCursorPos;
        textareaRef.current.selectionEnd = newCursorPos;
        textareaRef.current.focus();
      }
    });
  },
  [text, mentionTriggerPos],
);
```

**Mention close handler:**
```typescript
const handleMentionClose = useCallback(() => {
  setMentionOpen(false);
  setMentionQuery("");
  setMentionTriggerPos(-1);
  mentionFetchedRef.current = false;
}, []);
```

**Modified handleKeyDown** (lines 78-87):
When mention dropdown is open, intercept ArrowDown/ArrowUp/Enter/Escape. Cmd/Ctrl+Enter always submits regardless of dropdown state.

```typescript
const handleKeyDown = useCallback(
  (e: KeyboardEvent<HTMLTextAreaElement>) => {
    // Cmd/Ctrl+Enter always submits
    if (e.key === "Enter" && (e.metaKey || e.ctrlKey)) {
      e.preventDefault();
      handleSubmit();
      return;
    }

    // When mention dropdown is open, handle navigation
    if (mentionOpen && filteredMentionSuggestions.length > 0) {
      if (e.key === "ArrowDown") {
        e.preventDefault();
        setMentionFocusedIndex((prev) =>
          prev < filteredMentionSuggestions.length - 1 ? prev + 1 : 0
        );
        return;
      }
      if (e.key === "ArrowUp") {
        e.preventDefault();
        setMentionFocusedIndex((prev) =>
          prev > 0 ? prev - 1 : filteredMentionSuggestions.length - 1
        );
        return;
      }
      if (e.key === "Enter") {
        e.preventDefault();
        const selected = filteredMentionSuggestions[mentionFocusedIndex];
        if (selected) handleMentionSelect(selected.name);
        return;
      }
      if (e.key === "Escape") {
        e.preventDefault();
        handleMentionClose();
        return;
      }
    }
  },
  [handleSubmit, mentionOpen, filteredMentionSuggestions, mentionFocusedIndex, handleMentionSelect, handleMentionClose],
);
```

