// This is the fallback strategy — preferred over Better Auth hooks
// because the hook API may not cleanly support all counters. Response-
// status-based counting gives reliable observability regardless of
// Better Auth version changes.
app.use("/api/auth/*", async (c, next) => {
  await next();
  if (c.req.path.includes("/sign-in") && c.req.method === "POST") {
    metrics.signInAttempts.inc();
    if (c.res.status === 200) metrics.sessionCreated.inc();
  }
  if (c.req.path.endsWith("/token") && c.req.method === "POST" && c.res.status === 200) {
    metrics.tokenIssued.inc();
