  logger.info("auth service starting", {
    port: env.PORT,
    metricsPort: env.METRICS_PORT,
    providers,
    mode: providers.length > 0 ? "oauth" : "minimal",
  });

  // Start main public server
  const server = serve({
    fetch: app.fetch,
    port: env.PORT,
  }, (info) => {
    logger.info("auth service listening", { port: info.port });
  });

  // Start internal metrics server on separate port
  const metricsServer = serve({
    fetch: metricsApp.fetch,
    port: env.METRICS_PORT,
  }, (info) => {
    logger.info("metrics server listening (internal only)", { port: info.port });
  });

  // Graceful shutdown
  let shuttingDown = false;
  const shutdown = async (signal: string) => {
    if (shuttingDown) return; // prevent double-close
    shuttingDown = true;
    logger.info("shutdown initiated", { signal });
    server.close();
    metricsServer.close();
    await closeDb();
    logger.info("shutdown complete");
    process.exit(0);
  };

  process.on("SIGINT", () => shutdown("SIGINT"));
  process.on("SIGTERM", () => shutdown("SIGTERM"));
}

main().catch((err) => {
  logger.error("fatal startup error", {
    error: err instanceof Error ? err.message : String(err),
  });
  process.exit(1);
});
```

