func TestWithTx_CancelledCtxDoesNotDiscardWork(t *testing.T) {
    store := newTestStore(t, t.TempDir()+"/test.db")
    defer store.Close()

    // Create a context that we cancel inside fn()
    ctx, cancel := context.WithCancel(context.Background())

    err := store.withTx(ctx, func(conn *sql.Conn) error {
        _, err := conn.ExecContext(ctx, "INSERT INTO config (key, value) VALUES (?, ?)", "cancel_test", "survived")
        if err != nil {
            return err
        }
        cancel() // Cancel AFTER work is done but BEFORE commit
        return nil
    })
    if err != nil {
        t.Fatalf("withTx should succeed despite ctx cancellation: %v", err)
    }

    // Verify the insert was committed, not rolled back
    var value string
    err = store.db.QueryRowContext(context.Background(), "SELECT value FROM config WHERE key = ?", "cancel_test").Scan(&value)
    if err != nil {
        t.Fatalf("Data should be committed despite ctx cancellation: %v", err)
    }
    if value != "survived" {
        t.Errorf("Expected 'survived', got %q", value)
    }
}
