```typescript
import type { components } from "@/types/generated/openapi";
import type { LoomAgentStatus } from "./agent";

/** Single agent entry from GET /api/workspaces/{ws}/agents/status. */
export type AgentStatusEntry = components["schemas"]["AgentStatusEntry"];

/** Top-level response data from the agent status endpoint. */
export type WorkspaceAgentStatusResponse = components["schemas"]["WorkspaceAgentStatusResponse"];

/**
 * Map an AgentStatusEntry (from workspace-scoped endpoint) to LoomAgentStatus
 * (consumed by all existing agent UI components).
 *
 * This is the bridge between the new daemon-enriched endpoint and the 11
 * existing consumers that expect the MonitorAgentStatus-based shape.
 */
export function mapToLoomAgentStatus(
  entry: AgentStatusEntry,
  workspaceName: string,
): LoomAgentStatus {
  return {
    // Core fields (required by MonitorAgentStatus base)
    name: entry.worktree,
    branch: entry.branch,
    status: entry.status,
    ahead: entry.ahead,
    behind: entry.behind,

    // Optional base fields
    role: entry.role,
    repo: entry.repo ?? undefined,
    workspace: workspaceName,
    daemon_managed: true,

    // Extended fields (from LoomAgentStatus extensions)
    worktree_path: entry.worktree_path,

    // New daemon supervision fields (optional — existing consumers ignore these)
    pid: entry.pid,
    supervisor_status: entry.supervisor_status,
    restart_count: entry.restart_count,
    last_error_class: entry.last_error_class ?? undefined,
    backoff_until: entry.backoff_until ?? undefined,
    stop_reason: entry.stop_reason ?? undefined,
    task_id: entry.task_id ?? undefined,
    epic_id: entry.epic_id ?? undefined,
    yield_requested: entry.yield_requested,
    yield_reason: entry.yield_reason ?? undefined,
    yield_requested_at: entry.yield_requested_at ?? undefined,
    changes_count: entry.changes,
  };
}

/**
 * Batch-convert a full status response to LoomAgentStatus[].
 * Convenience wrapper used by the agent store.
 */
export function mapAgentStatusResponse(
  response: WorkspaceAgentStatusResponse,
  workspaceName: string,
): LoomAgentStatus[] {
  return response.agents.map((entry) =>
    mapToLoomAgentStatus(entry, workspaceName),
  );
}
```

