```typescript
import { api, apiErrorFromResponse } from "@/api/common";
import type { WorkspaceAgentStatusResponse } from "@/types";

/**
 * Fetch merged agent status for a workspace.
 * Returns daemon supervision + git enrichment data for all agents.
 *
 * @param workspaceId - Workspace UUID
 * @param options - Optional abort signal for cancellation
 */
export async function fetchWorkspaceAgentStatus(
  workspaceId: string,
  options?: { signal?: AbortSignal },
): Promise<WorkspaceAgentStatusResponse> {
  const { data, error, response } = await api.GET(
    "/api/workspaces/{ws}/agents/status",
    {
      params: { path: { ws: workspaceId } },
      ...(options?.signal ? { signal: options.signal } : {}),
    },
  );
  if (error) throw apiErrorFromResponse(error, response);

  // The endpoint wraps in { success, data } envelope
  const envelope = data as unknown as {
    success: boolean;
    data: WorkspaceAgentStatusResponse;
  };
  if (!envelope.success) {
    throw apiErrorFromResponse("Agent status request failed", response);
  }
  return envelope.data;
}
```

Note: The exact unwrapping depends on how task .8 structures the response envelope. The design shows `{ success: true, data: { agents: [...], ipc_socket_active, daemon_pid, daemon_started_at } }`. If the openapi-fetch generated type already includes the envelope, the unwrap changes to match. The implementation agent should verify the generated type shape after running codegen and adjust accordingly.

