\`\`\`typescript
async function fetchAgentData(
  set: (partial: Partial<AgentStore>) => void,
  get: () => AgentStore,
  workspaceId: string,
  workspaceName: string,
): Promise<void> {
  if (agentFetchInProgress) return;
  agentFetchInProgress = true;
  agentFetchStartTime = Date.now();
  set({ isLoading: true });
  try {
    const response: WorkspaceAgentStatusResponse = await withTimeout(
      fetchWorkspaceAgentStatus(workspaceId),
      FETCH_TIMEOUT_MS,
      "Agent status fetch",
    );
    const agents = mapAgentStatusResponse(response, workspaceName);
    const now = Date.now();
    set({
      agents,
      isConnected: true,
      error: null,
      lastUpdated: now,
      isLoading: false,
    });
    reportSuccess(set);
    const state = get();
    set({
      connectionState: deriveConnectionState(true, false, state.wasEverConnected, state.retryCountdown),
    });
  } catch (err) {
    const error = err instanceof Error ? err : new Error(String(err));
    set({ error, isConnected: false, isLoading: false });
    reportFailure(set, get);
    const state = get();
    set({
      connectionState: deriveConnectionState(false, false, state.wasEverConnected, state.retryCountdown),
    });
  } finally {
    agentFetchInProgress = false;
  }
}
\`\`\`

