async function fetchMonitorData(
  set: (partial: Partial<AgentStore>) => void,
  workspaceId: string,
): Promise<void> {
  if (monitorFetchInProgress) return;
  monitorFetchInProgress = true;
  monitorFetchStartTime = Date.now();
  try {
    const statusResult = await withTimeout(
      fetchWorkspaceMonitorStatus(workspaceId),
      FETCH_TIMEOUT_MS,
      "Monitor status fetch",
    );
    set({
      tasks: statusResult.tasks,
      agentTasks: statusResult.agentTasks,
      sync: statusResult.sync,
