      "Monitor tasks fetch",
    );
    set({ taskLists: tasksResult });
  } catch (taskError) {
    console.warn(
      "Workspace monitor tasks fetch failed:",
      taskError instanceof Error ? taskError.message : String(taskError),
    );
  }

  monitorFetchInProgress = false;
}
