**New store action: \`startSSEDriven\`** (added to AgentStoreActions interface and store implementation):
\`\`\`typescript
startSSEDriven(
  workspaceId: string,
  workspaceName: string,
  subscribeFn: SubscribeFn,
): void {
  // Clean up previous lifecycle
  if (isPolling) {
    get().stopPolling();
  }

  isPolling = true;
  activeWorkspaceId = workspaceId;
  activeWorkspaceName = workspaceName;

  // Initial loads
  void fetchAgentData(set, get, workspaceId, workspaceName);
  void fetchMonitorData(set, workspaceId);

  // Subscribe to agent_state_change SSE events
  sseUnsubscribe = subscribeFn(
    (_mutation: MutationPayload) => {
      // Watchdog: reset stale agent fetch lock
      if (agentFetchInProgress && Date.now() - agentFetchStartTime > WATCHDOG_TIMEOUT_MS) {
        console.warn("Agent fetch watchdog: force-resetting stale fetch lock (SSE path)");
        agentFetchInProgress = false;
      }
      void fetchAgentData(set, get, workspaceId, workspaceName);
    },
    { types: ["agent_state_change"] },
  );

  // 5s polling timer for monitor data (tasks/sync/stats)
  monitorIntervalId = setInterval(() => {
    // Watchdog for monitor fetch
    if (monitorFetchInProgress && Date.now() - monitorFetchStartTime > WATCHDOG_TIMEOUT_MS) {
      console.warn("Monitor fetch watchdog: force-resetting stale fetch lock");
      monitorFetchInProgress = false;
    }
    void fetchMonitorData(set, workspaceId);
  }, 5000);

  // Visibility change handler (same pattern as startPolling)
  if (typeof document !== "undefined") {
    visibilityHandler = () => {
      if (document.visibilityState === "visible") {
        agentFetchInProgress = false;
        monitorFetchInProgress = false;
        void fetchAgentData(set, get, workspaceId, workspaceName);
        void fetchMonitorData(set, workspaceId);
      }
    };
    document.addEventListener("visibilitychange", visibilityHandler);
  }
}
\`\`\`

**Update \`stopPolling\`**: Add SSE and monitor timer cleanup:
\`\`\`typescript
stopPolling(): void {
  // SSE cleanup
  if (sseUnsubscribe) {
    sseUnsubscribe();
    sseUnsubscribe = null;
  }

  // Monitor timer cleanup
  if (monitorIntervalId) {
    clearInterval(monitorIntervalId);
    monitorIntervalId = null;
  }

  // Original poll timer cleanup (fallback path)
  if (pollIntervalId) {
    clearInterval(pollIntervalId);
    pollIntervalId = null;
  }

  clearRetryTimers();
  clearStaleBannerTimer();

  if (visibilityHandler && typeof document !== "undefined") {
    document.removeEventListener("visibilitychange", visibilityHandler);
    visibilityHandler = null;
  }

  isPolling = false;
  activeWorkspaceId = null;
  activeWorkspaceName = null;

  const state = get();
  set({
    retryCountdown: 0,
    connectionState: deriveConnectionState(state.isConnected, false, state.wasEverConnected, 0),
  });
}
