```go
// ReadDaemonSupervisorState reads the daemon state file at statePath and
// converts it to the webui DTO. Returns os.ErrNotExist if the file is missing.
func ReadDaemonSupervisorState(statePath string) (*webui.DaemonSupervisorData, error) {
    state, err := daemon.ReadStateFile(statePath)
    if err != nil {
        return nil, err
    }
    agents := make([]webui.DaemonAgentEntry, len(state.Agents))
    for i, a := range state.Agents {
        agents[i] = webui.DaemonAgentEntry{
            Worktree:       a.Worktree,
            Role:           a.Role,
            Repo:           a.Repo,
            PID:            a.PID,
            Status:         a.Status,
            TaskID:         a.TaskID,
            EpicID:         a.EpicID,
            CurrentBackend: a.CurrentBackend,
            RestartCount:   a.RestartCount,
            LastStart:      a.LastStart,
            LastExit:       a.LastExit,
            LastExitCode:   a.LastExitCode,
            StopReason:     a.StopReason,
            StoppedAt:      a.StoppedAt,
            WorktreePath:   a.WorktreePath,
            LastErrorClass: a.LastErrorClass,
            NoWorkCount:    a.NoWorkCount,
            BackoffUntil:   a.BackoffUntil,
            RemoteBranch:   a.RemoteBranch,
        }
    }
    return &webui.DaemonSupervisorData{
        PID:           state.PID,
        StartedAt:     state.StartedAt,
        UptimeSeconds: time.Since(state.StartedAt).Seconds(),
        Agents:        agents,
    }, nil
}

// ReadDaemonConfig loads and marshals the daemon config. projectDir MUST be
// the workspace root directory (e.g., WorkspaceDaemonPaths.WorkDir) — NOT the
// loom.yaml file path. LoadDaemonConfig locates loom.yaml inside projectDir.
func ReadDaemonConfig(projectDir string) (json.RawMessage, error) {
    cfg, err := config.LoadDaemonConfig(projectDir)
    if err != nil {
        return nil, err
    }
    data, err := json.Marshal(cfg)
    if err != nil {
        return nil, fmt.Errorf("marshal daemon config: %w", err)
    }
    return json.RawMessage(data), nil
}
```

