```go
// BuildWorkspaceAgentControlResolver returns a resolver that, given a
// workspace ID, produces an agentcontrol.AgentControlFn bound to that
// workspace's daemon control socket. Returns (nil, error) for any wsID
// the inner pathResolver cannot map — callers must map the error to 503.
//
// The per-op deadline map is captured once and reused across all returned
// closures so deadline tuning lives in one place.
func BuildWorkspaceAgentControlResolver(
    pathResolver func(wsID string) (*webui.WorkspaceDaemonPaths, error),
) agentcontrol.AgentControlResolverFn {
    if pathResolver == nil {
        return nil
    }
    opDeadline := map[string]time.Duration{
        "agent_yield":   5 * time.Second,
        "agent_list":    5 * time.Second,
        "agent_start":   10 * time.Second,
        "agent_stop":    35 * time.Second, // daemon write deadline is 20s; 15s buffer
        "agent_restart": 80 * time.Second, // yieldTimeout(default 60s) + 20s buffer
    }
    return func(wsID string) (agentcontrol.AgentControlFn, error) {
        paths, err := pathResolver(wsID)
        if err != nil {
            return nil, fmt.Errorf("resolve workspace %q control socket: %w", wsID, err)
        }
        if paths == nil || paths.SocketPath == "" {
            return nil, fmt.Errorf("resolve workspace %q control socket: no socket path", wsID)
        }
        socketPath := paths.SocketPath
        return func(op, agentName string, force bool) (*agentcontrol.AgentControlResult, error) {
            deadline := opDeadline[op]
            if deadline == 0 {
                deadline = 30 * time.Second
            }
            return sendControlRequest(socketPath, op, agentName, force, deadline)
        }, nil
    }
}
```

The socket path is captured when the resolver is called, before dialing. That preserves the old "re-resolve per call" semantics because the outer `BuildWorkspaceDaemonResolver` already recomputes `SocketPath` from the workspace's current daemon.pid on each invocation (daemon.go:289-294). Capturing once inside the returned closure is therefore safe and simpler than re-resolving on every send.

