func TestHandleAgentControl_DispatchesByWorkspaceID(t *testing.T) {
    // Two workspaces, two distinct control functions. The resolver picks
    // one based on wsID. Assert that a request to /api/workspaces/ws2/...
    // invokes ws2's fn — not ws1's — proving that the {ws} path param
    // drives dispatch rather than silently falling back to a default.
    var ws1Called, ws2Called int
    resolver := AgentControlResolverFn(func(wsID string) (AgentControlFn, error) {
        switch wsID {
        case "ws1":
            return func(op, name string, force bool) (*AgentControlResult, error) {
                ws1Called++
                return &AgentControlResult{Success: true}, nil
            }, nil
        case "ws2":
            return func(op, name string, force bool) (*AgentControlResult, error) {
                ws2Called++
                return &AgentControlResult{Success: true}, nil
            }, nil
        default:
            return nil, fmt.Errorf("unknown workspace: %s", wsID)
        }
    })

    mux := http.NewServeMux()
    mux.HandleFunc("POST /api/workspaces/{ws}/agents/{name}/start", handleAgentStart(resolver))

    req := httptest.NewRequest("POST", "/api/workspaces/ws2/agents/falcon/start", nil)
    rec := mustServeWithWorkspace(t, mux, req, "ws2")
    if rec.Code != http.StatusOK {
        t.Fatalf("status = %d, want 200; body = %s", rec.Code, rec.Body.String())
    }
    if ws1Called != 0 {
        t.Errorf("ws1 fn called %d times for a ws2 request; want 0 — silent cross-workspace dispatch", ws1Called)
    }
    if ws2Called != 1 {
        t.Errorf("ws2 fn called %d times; want 1", ws2Called)
    }
}
