package daemon

import "net/http"

// Module registers workspace-scoped daemon inspection routes.
// Constructed only when WorkspaceDaemonResolver is non-nil.
type Module struct {
    resolverFn DaemonResolverFn
}

func NewModule(resolverFn DaemonResolverFn) *Module {
    return &Module{resolverFn: resolverFn}
}

func (m *Module) Register(mux *http.ServeMux) {
    mux.HandleFunc("GET /api/workspaces/{ws}/daemon/supervisor", handleWsSupervisor(m.resolverFn))
    mux.HandleFunc("GET /api/workspaces/{ws}/daemon/config", handleWsConfig(m.resolverFn))
}
```

