The new hook file. Structure:

```typescript
/**
 * useDaemonHealthDetail - React hook for detailed daemon health monitoring.
 * Polls GET /api/health and GET /api/metrics in parallel every 10s.
 * Returns structured health and metrics data for the daemon health dashboard.
 * Distinct from useDaemonHealth (connectivity probe with backoff overlay).
 */

import { useState, useEffect, useCallback, useRef } from "react";

import { ApiError } from "@/api/client";
import { fetchFullHealth } from "@/api/health";
import type { FullHealthResponse } from "@/api/health";
import { fetchSSEMetrics } from "@/api/observability";
import type { SSEMetricsData } from "@/api/observability";

export interface UseDaemonHealthDetailOptions {
  /** Poll interval in ms (default: 10000) */
  pollInterval?: number;
  /** Whether to fetch (default: true) */
  enabled?: boolean;
}

export interface UseDaemonHealthDetailResult {
  health: FullHealthResponse | null;
  metrics: SSEMetricsData | null;
  isLoading: boolean;
  error: Error | null;
  lastUpdated: Date | null;
  refetch: () => Promise<void>;
}

/**
 * Extract FullHealthResponse from an ApiError 503 response.
 * The Go handler returns 503 with a full HealthStatus body for degraded/unhealthy states.
 * Returns null if the body isn't a valid health response.
 */
function extractHealthFrom503(err: ApiError): FullHealthResponse | null {
  if (err.status !== 503 || !err.body || typeof err.body !== "object") {
    return null;
  }
  const body = err.body as Record<string, unknown>;
  if (typeof body.status === "string" && body.daemon && typeof body.daemon === "object") {
    return body as unknown as FullHealthResponse;
  }
  return null;
}

export function useDaemonHealthDetail(
  options?: UseDaemonHealthDetailOptions,
): UseDaemonHealthDetailResult {
  const { pollInterval = 10000, enabled = true } = options ?? {};

  const [health, setHealth] = useState<FullHealthResponse | null>(null);
  const [metrics, setMetrics] = useState<SSEMetricsData | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<Error | null>(null);
  const [lastUpdated, setLastUpdated] = useState<Date | null>(null);

  const fetchInProgressRef = useRef(false);
  const mountedRef = useRef(true);

  const fetchData = useCallback(async () => {
    if (fetchInProgressRef.current) return;

    fetchInProgressRef.current = true;
    setIsLoading(true);

    try {
      const [healthResult, metricsResult] = await Promise.allSettled([
        fetchFullHealth(),
        fetchSSEMetrics(),
      ]);

      if (!mountedRef.current) return;

      // Process health result
      let newHealth: FullHealthResponse | null = null;
      let healthErr: Error | null = null;
      if (healthResult.status === "fulfilled") {
        newHealth = healthResult.value;
      } else {
        // Check if 503 contains usable health data
        const reason = healthResult.reason;
        if (reason instanceof ApiError) {
          const extracted = extractHealthFrom503(reason);
          if (extracted) {
            newHealth = extracted;
          } else {
            healthErr = reason;
          }
        } else {
          healthErr = reason instanceof Error ? reason : new Error(String(reason));
        }
      }

      // Process metrics result
      let newMetrics: SSEMetricsData | null = null;
      let metricsErr: Error | null = null;
      if (metricsResult.status === "fulfilled") {
        newMetrics = metricsResult.value;
      } else {
        const reason = metricsResult.reason;
        metricsErr = reason instanceof Error ? reason : new Error(String(reason));
      }

      setHealth(newHealth);
      setMetrics(newMetrics);

      // Only set error when BOTH failed to provide data
      if (newHealth === null && newMetrics === null) {
        setError(healthErr ?? metricsErr);
      } else {
        setError(null);
      }

      setLastUpdated(new Date());
    } catch (err) {
      // Unexpected error in the allSettled logic itself (shouldn't happen)
      if (mountedRef.current) {
        setError(err instanceof Error ? err : new Error(String(err)));
      }
    } finally {
      if (mountedRef.current) {
        setIsLoading(false);
      }
      fetchInProgressRef.current = false;
    }
  }, []);

  const refetch = useCallback(async () => {
    await fetchData();
  }, [fetchData]);

  useEffect(() => {
    mountedRef.current = true;

    if (!enabled) return;

    void fetchData();

    let intervalId: ReturnType<typeof setInterval> | null = null;
    if (pollInterval > 0) {
      intervalId = setInterval(() => {
        void fetchData();
      }, pollInterval);
    }

    const handleVisibilityChange = () => {
      if (document.visibilityState === "visible") {
        fetchInProgressRef.current = false;
        void fetchData();
      }
    };
    document.addEventListener("visibilitychange", handleVisibilityChange);

    return () => {
      mountedRef.current = false;
      if (intervalId) clearInterval(intervalId);
      document.removeEventListener("visibilitychange", handleVisibilityChange);
    };
  }, [enabled, pollInterval, fetchData]);

  return { health, metrics, isLoading, error, lastUpdated, refetch };
}
```

