export function DaemonHealthDashboard({ className }: DaemonHealthDashboardProps): JSX.Element {
  const { health, metrics, isLoading, error, lastUpdated, refetch } =
    useDaemonHealthDetail({ pollInterval: 10000 });

  // Loading guard: only show skeleton on initial load (no data yet)
  if (isLoading && !health && !metrics) {
    return <div className={rootClassName}><LoadingSkeleton.Observability /></div>;
  }

  // Error guard: only show error when no data at all
  if (error && !health && !metrics) {
    return <div className={rootClassName}>
      <ErrorDisplay variant="fetch-error" error={error} showDetails onRetry={() => void refetch()} />
    </div>;
  }

  // Stale data: have old data but current fetch errored
  // Renders staleIndicator banner + cards with stale data

  // Conditional fleet card
  const showFleet = metrics != null && metrics.loom_fleet_claims_total !== undefined;

  return (
    <div className={rootClassName}>
      {error && (health || metrics) && <StaleIndicator lastUpdated={lastUpdated} onRetry={refetch} />}

      <DaemonOverviewCard
        status={health?.status ?? null}
        connected={health?.daemon.connected ?? false}
        uptime={health?.daemon.uptime}
        version={health?.daemon.version}
        error={health?.daemon.error}
      />

      <div className={styles.twoColumnRow}>
        <ConnectionPoolCard
          pool={health?.pool ?? null}
          workspacePools={health?.workspace_pools ?? null}
        />
        <CircuitBreakerCard
          state={health?.circuit_breaker?.state ?? null}
          failureCount={health?.circuit_breaker?.failure_count ?? 0}
          lastStateChange={health?.circuit_breaker?.last_state_change ?? null}
        />
      </div>

      <SSEHubCard
        connectedClients={metrics?.connected_clients ?? null}
        droppedMutations={metrics?.dropped_mutations ?? null}
        retryQueueDepth={metrics?.retry_queue_depth ?? null}
        uptimeSeconds={metrics?.uptime_seconds ?? null}
      />

      {showFleet && (
        <FleetMetricsCard
          claimsTotal={metrics!.loom_fleet_claims_total!}
          claimsSuccess={metrics!.loom_fleet_claims_success ?? 0}
          claimsCollision={metrics!.loom_fleet_claims_collision ?? 0}
          claimsTimeout={metrics!.loom_fleet_claims_timeout ?? 0}
          timeoutsTotal={metrics!.loom_fleet_timeouts_total ?? 0}
        />
      )}
    </div>
  );
}
