### Mock Setup Function

```typescript
async function setupMultiWorkspaceMocks(page: Page): Promise<{ setActiveWorkspace: (id: string) => void }> {
  let currentWsId = WS_A.id;

  const setActiveWorkspace = (id: string) => { currentWsId = id; };

  // Workspace API: /api/workspaces/active and /api/workspaces/{id}
  await page.route("**/api/workspaces/**", async (route) => {
    const url = route.request().url();
    if (url.includes("/active")) {
      const data = currentWsId === WS_A.id ? workspaceDataForA : workspaceDataForB;
      await route.fulfill({ status: 200, contentType: "application/json", body: JSON.stringify({ success: true, data }) });
    } else if (url.includes(WS_A.id)) {
      await route.fulfill({ status: 200, contentType: "application/json", body: JSON.stringify({ success: true, data: workspaceDataForA }) });
    } else if (url.includes(WS_B.id)) {
      await route.fulfill({ status: 200, contentType: "application/json", body: JSON.stringify({ success: true, data: workspaceDataForB }) });
    } else {
      await route.fallback();
    }
  });

  // Issues (workspace-aware): /api/ready
  await page.route("**/api/ready", async (route) => {
    const issues = currentWsId === WS_A.id ? issuesA : issuesB;
    await route.fulfill({ status: 200, contentType: "application/json", body: JSON.stringify({ success: true, data: issues }) });
  });

  // Loom agent status (workspace-aware)
  await page.route("**/localhost:9000/api/status", async (route) => {
    const status = currentWsId === WS_A.id ? loomStatusA : loomStatusB;
    await route.fulfill({ status: 200, contentType: "application/json", body: JSON.stringify(status) });
  });
  await page.route("**/localhost:9000/api/tasks", async (route) => {
    await route.fulfill({ status: 200, contentType: "application/json", body: JSON.stringify({ needs_planning: [], ready_to_implement: [], in_progress: [], needs_review: [], blocked: [] }) });
  });

  // Observability metrics
  await page.route("**/api/loom/api/observability/metrics", async (route) => {
    await route.fulfill({ status: 200, contentType: "application/json", body: JSON.stringify(mockMetrics) });
  });

  // Standard mocks (health, auth, stats, events, blocked)
  await page.route("**/api/health", async (route) => { await route.fulfill({ status: 200, contentType: "application/json", body: JSON.stringify({ status: "ok", daemon: true }) }); });
  await page.route("**/api/auth/token", async (route) => { await route.fulfill({ status: 200, contentType: "application/json", body: JSON.stringify({ token: "test-token" }) }); });
  await page.route("**/api/stats", async (route) => { await route.fulfill({ status: 200, contentType: "application/json", body: JSON.stringify({ success: true, data: createStats() }) }); });
  await page.route("**/api/blocked", async (route) => { await route.fulfill({ status: 200, contentType: "application/json", body: JSON.stringify({ success: true, data: [] }) }); });
  await page.route("**/api/events", async (route) => { await route.abort(); });

  return { setActiveWorkspace };
}
```

