import { test as base, expect } from '@playwright/test';

interface ScreenshotFixtures {
  screenshotPage: Page; // Pre-configured page with auth/SSE/loom mocked
}

export const test = base.extend<ScreenshotFixtures>({
  screenshotPage: async ({ page }, use) => {
    // 1. Mock /api/auth/token → { token: "test-token-screenshot" }
    // 2. Abort /api/events** (prevents SSE networkidle timeout)
    // 3. Abort /api/loom/** (prevents loom server timeouts)
    await use(page);
  },
});

// Re-export waitForStableContent as standalone helper
export async function waitForStableContent(page: Page): Promise<void> {
  await page.waitForLoadState('networkidle');
  await page.waitForTimeout(100);
}

export { expect };
